from fastapi import FastAPI, Depends, HTTPException, status
from pydantic import BaseModel, Field
from typing import List, Optional

app = FastAPI(title="Products API", version="1.0.0")

fake_db: dict = {}

class ProductBase(BaseModel):
    name: str = Field(..., min_length=2, max_length=100)
    price: float = Field(..., gt=0)
    stock: int = Field(default=0, ge=0)
    description: Optional[str] = None

class ProductCreate(ProductBase):
    pass

class ProductResponse(ProductBase):
    id: int

    class Config:
        from_attributes = True

@app.post("/products/", response_model=ProductResponse, status_code=201)
def create_product(product: ProductCreate):
    product_id = len(fake_db) + 1
    product_dict = product.model_dump()
    product_dict["id"] = product_id
    fake_db[product_id] = product_dict
    return product_dict

@app.get("/products/", response_model=List[ProductResponse])
def list_products(skip: int = 0, limit: int = 10):
    products = list(fake_db.values())[skip : skip + limit]
    return products

@app.get("/products/{product_id}", response_model=ProductResponse)
def get_product(product_id: int):
    if product_id not in fake_db:
        raise HTTPException(status_code=404, detail="Product not found")
    return fake_db[product_id]

@app.put("/products/{product_id}", response_model=ProductResponse)
def update_product(product_id: int, product: ProductCreate):
    if product_id not in fake_db:
        raise HTTPException(status_code=404, detail="Product not found")
    product_dict = product.model_dump()
    product_dict["id"] = product_id
    fake_db[product_id] = product_dict
    return product_dict

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)

